CREATE VIEW gold.rpt_sales_office_performance AS WITH office_keys AS (SELECT sales_off FROM gold.corr_sales_sales_office UNION SELECT sales_off FROM gold.corr_picking_sales_office UNION SELECT sales_off FROM gold.corr_unloading_sales_office) SELECT '2024Q4' reporting_period, 202410 period_start_calmonth, 202412 period_end_calmonth, 'sales_office_quarter' reporting_grain, k.sales_off, s.bill_val sales_bill_val, s.sales_lines, p.delay_rate picking_delay_rate, p.avg_pick_min, p.pick_rows, u.avg_unload_min, u.unload_rows, s.sales_off IS NOT NULL has_sales, p.sales_off IS NOT NULL has_picking, u.sales_off IS NOT NULL has_unloading, CASE WHEN s.sales_lines > 0 THEN CAST(p.pick_rows AS DOUBLE) / s.sales_lines END pick_rows_per_sales_line FROM office_keys k LEFT OUTER JOIN gold.corr_sales_sales_office s ON k.sales_off = s.sales_off LEFT OUTER JOIN gold.corr_picking_sales_office p ON k.sales_off = p.sales_off LEFT OUTER JOIN gold.corr_unloading_sales_office u ON k.sales_off = u.sales_off